        port_counts = [len(d.get("ports", [])) for d in self.circuit["devices"]]
        avg_ports = float(np.mean(port_counts)) if port_counts else 0.0
        type_map = {"mzi": 0, "ring": 1, "mmi": 2, "coupler": 3}
        type_dist = np.zeros(4, dtype=np.float64)
